#!/usr/bin/env python3
"""
tools/render.py
Renders preview screenshots of the prototype without Roblox:

  * a small software 3D renderer (perspective camera, lathe-turned pieces,
    Lambert + rim shading, painter's algorithm) that mirrors Board3D.lua
  * a pixel-accurate reimplementation of Hud.lua's layout and palette
  * positions + move lists come from renders/states.json (generated by the
    real chess engine, scripts/dump_render_states.lua)

Usage:  python3 tools/render.py
"""

import json
import math
import os

import numpy as np
from PIL import Image, ImageDraw, ImageFilter, ImageFont

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
RENDERS = os.path.join(ROOT, "renders")
STATES = os.path.join(RENDERS, "states.json")

W, H = 1600, 1000
SS = 2  # supersampling factor
TILE = 4.0

# ---------------------------------------------------------------- palette
def rgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


P = {
    "light": rgb("#EEEED2"),
    "dark": rgb("#769656"),
    "border": rgb("#262421"),
    "white_piece": rgb("#F2EFE6"),
    "black_piece": rgb("#3E3B36"),
    "last_move": rgb("#FFFF33"),
    "select": rgb("#F5F682"),
    "legal_dot": rgb("#1E1E19"),
    "check": rgb("#EB463C"),
    "panel": rgb("#262421"),
    "panel_raised": rgb("#302E2B"),
    "panel_hover": rgb("#3C3A37"),
    "stroke": rgb("#1C1A18"),
    "accent": rgb("#81B64C"),
    "accent_hover": rgb("#9BCF5E"),
    "danger": rgb("#CA343C"),
    "text": rgb("#FFFFFF"),
    "text_muted": rgb("#B2B0AD"),
    "text_dim": rgb("#8C8A87"),
    "clock_low": rgb("#FA6256"),
    "win": rgb("#81B64C"),
    "loss": rgb("#FA6256"),
    "bg": rgb("#141312"),
}

FONT_DIR = "/usr/share/fonts/truetype/dejavu"
FONTS = {}


def font(size, weight="bold", mono=False):
    key = (size, weight, mono)
    if key in FONTS:
        return FONTS[key]
    if mono:
        path = os.path.join(FONT_DIR, "DejaVuSansMono-Bold.ttf")
    elif weight == "black":
        path = os.path.join(FONT_DIR, "DejaVuSans-Bold.ttf")
    elif weight == "bold":
        path = os.path.join(FONT_DIR, "DejaVuSans-Bold.ttf")
    else:
        path = os.path.join(FONT_DIR, "DejaVuSans.ttf")
    f = ImageFont.truetype(path, size * SS)
    FONTS[key] = f
    return f


# ---------------------------------------------------------------- 3D maths
def norm(v):
    n = np.linalg.norm(v)
    return v / n if n > 1e-9 else v


class Camera:
    def __init__(self, eye, focus, fov=42.0, x_shift=0.0, width=W, height=H):
        self.eye = np.array(eye, dtype=float)
        self.focus = np.array(focus, dtype=float)
        forward = norm(self.focus - self.eye)
        up = np.array([0.0, 1.0, 0.0])
        right = norm(np.cross(forward, up))
        true_up = np.cross(right, forward)
        self.R = np.stack([right, true_up, forward])
        self.fov = fov
        self.x_shift = x_shift
        self.width = width
        self.height = height
        self.focal = (height / 2.0) / math.tan(math.radians(fov) / 2.0)

    def project(self, pts):
        pts = np.asarray(pts, dtype=float)
        d = (pts - self.eye) @ self.R.T
        z = np.clip(d[:, 2], 1e-3, None)
        x = self.width / 2.0 + self.x_shift + self.focal * d[:, 0] / z
        y = self.height / 2.0 - self.focal * d[:, 1] / z
        return np.stack([x, y], axis=1), z


LIGHT = norm(np.array([-0.42, 1.0, 0.55]))
AMBIENT = 0.46


def shade(base, normal, view, spec_strength=0.30, shininess=28.0, rim_strength=0.30):
    n = norm(np.asarray(normal, dtype=float))
    v = norm(np.asarray(view, dtype=float))
    diffuse = max(0.0, float(np.dot(n, LIGHT)))
    half = norm(LIGHT + v)
    specular = max(0.0, float(np.dot(n, half))) ** shininess * spec_strength
    rim = max(0.0, 1.0 - abs(float(np.dot(n, v)))) ** 2.6 * rim_strength
    k = AMBIENT + 0.72 * diffuse + rim
    return tuple(int(min(255, max(0, c * k + 255 * specular))) for c in base)


# ---------------------------------------------------------------- geometry
def lathe(profile, segments=30):
    """Surface of revolution around Y. profile = [(radius, y), ...]"""
    polys = []
    angles = np.linspace(0, 2 * math.pi, segments + 1)
    for i in range(segments):
        a0, a1 = angles[i], angles[i + 1]
        c0, s0 = math.cos(a0), math.sin(a0)
        c1, s1 = math.cos(a1), math.sin(a1)
        for j in range(len(profile) - 1):
            r0, y0 = profile[j]
            r1, y1 = profile[j + 1]
            p00 = np.array([r0 * c0, y0, r0 * s0])
            p01 = np.array([r0 * c1, y0, r0 * s1])
            p10 = np.array([r1 * c0, y1, r1 * s0])
            p11 = np.array([r1 * c1, y1, r1 * s1])
            if r0 < 1e-6 and r1 < 1e-6:
                continue
            if r0 < 1e-6:
                poly = [p00, p11, p01]
            elif r1 < 1e-6:
                poly = [p00, p10, p01]
            else:
                poly = [p00, p10, p11, p01]
            dr = r1 - r0
            dy = y1 - y0
            # outward normal of the (radius, height) profile: (dy, -dr)
            am = (a0 + a1) / 2
            normal = norm(np.array([math.cos(am) * dy, -dr, math.sin(am) * dy]))
            polys.append((np.array(poly), normal))
    return polys


def sphere(radius, center, segs=16, rings=10):
    polys = []
    for i in range(rings):
        t0 = math.pi * i / rings
        t1 = math.pi * (i + 1) / rings
        for j in range(segs):
            a0 = 2 * math.pi * j / segs
            a1 = 2 * math.pi * (j + 1) / segs
            def pt(t, a):
                return np.array([
                    center[0] + radius * math.sin(t) * math.cos(a),
                    center[1] + radius * math.cos(t),
                    center[2] + radius * math.sin(t) * math.sin(a),
                ])
            p00, p01 = pt(t0, a0), pt(t0, a1)
            p10, p11 = pt(t1, a0), pt(t1, a1)
            poly = np.array([p00, p10, p11, p01])
            centroid = poly.mean(axis=0) - np.array(center)
            polys.append((poly, centroid))
    return polys


def rot_matrix(rx, ry, rz):
    rx, ry, rz = map(math.radians, (rx, ry, rz))
    cx, sx = math.cos(rx), math.sin(rx)
    cy, sy = math.cos(ry), math.sin(ry)
    cz, sz = math.cos(rz), math.sin(rz)
    Rx = np.array([[1, 0, 0], [0, cx, -sx], [0, sx, cx]])
    Ry = np.array([[cy, 0, sy], [0, 1, 0], [-sy, 0, cy]])
    Rz = np.array([[cz, -sz, 0], [sz, cz, 0], [0, 0, 1]])
    return Rz @ Ry @ Rx


def box(size, center, rot=(0, 0, 0)):
    sx, sy, sz = size[0] / 2, size[1] / 2, size[2] / 2
    corners = np.array([
        [-sx, -sy, -sz], [sx, -sy, -sz], [sx, sy, -sz], [-sx, sy, -sz],
        [-sx, -sy, sz], [sx, -sy, sz], [sx, sy, sz], [-sx, sy, sz],
    ], dtype=float)
    R = rot_matrix(*rot)
    corners = corners @ R.T + np.array(center, dtype=float)
    faces = [(0, 1, 2, 3), (5, 4, 7, 6), (4, 0, 3, 7), (1, 5, 6, 2), (4, 5, 1, 0), (3, 2, 6, 7)]
    polys = []
    for face in faces:
        poly = corners[list(face)]
        n = norm(np.cross(poly[1] - poly[0], poly[3] - poly[0]))
        if np.dot(n, poly.mean(axis=0) - np.array(center, dtype=float)) < 0:
            n = -n
        polys.append((poly, n))
    return polys


# ---------------------------------------------------------------- pieces
# The previews render the *actual* assets: assets/pieces/*.obj, the same meshes
# that get imported into Studio (see docs/ASSETS.md). If the meshes are missing,
# fall back to a crude lathe so the tool still runs.
PIECE_DIR = os.path.join(ROOT, "assets", "pieces")
PIECE_FILES = {
    "P": "pawn.obj", "R": "rook.obj", "N": "knight.obj",
    "B": "bishop.obj", "Q": "queen.obj", "K": "king.obj",
}
# knights are modelled facing +Z; turn them side-on so the head profile reads
PIECE_YAW = {"N": 90.0}

GEOM_CACHE = {}


def load_obj(path):
    verts, normals, faces = [], [], []
    with open(path) as fh:
        for line in fh:
            if line.startswith("v "):
                parts = line.split()
                verts.append((float(parts[1]), float(parts[2]), float(parts[3])))
            elif line.startswith("vn "):
                parts = line.split()
                normals.append((float(parts[1]), float(parts[2]), float(parts[3])))
            elif line.startswith("f "):
                idx = []
                for token in line.split()[1:]:
                    bits = token.split("/")
                    vi = int(bits[0]) - 1
                    ni = int(bits[2]) - 1 if len(bits) > 2 and bits[2] else vi
                    idx.append((vi, ni))
                faces.append(idx)
    return np.array(verts), faces, np.array(normals)


def piece_geometry(ptype, yaw=None):
    """Returns [(polygons (N,3), face normal)] for one piece type, cached by yaw."""
    if yaw is None:
        yaw = PIECE_YAW.get(ptype, 0.0)
    key = (ptype, yaw)
    if key in GEOM_CACHE:
        return GEOM_CACHE[key]

    path = os.path.join(PIECE_DIR, PIECE_FILES.get(ptype, "pawn.obj"))
    geoms = []
    if os.path.exists(path):
        verts, faces, normals = load_obj(path)
        for face in faces:
            vi = [f[0] for f in face]
            ni = [f[1] for f in face]
            poly = verts[vi]
            normal = normals[ni].mean(axis=0)
            geoms.append((poly, normal))
        if yaw:
            R = rot_matrix(0, yaw, 0)
            geoms = [(poly @ R.T, R @ np.asarray(n)) for poly, n in geoms]
    else:
        fallback = [(0, 0), (0.4, 0), (0.4, 0.2), (0.3, 0.5), (0.4, 0.7), (0.3, 1.0), (0, 1.1)]
        for poly, n in lathe([(r * 1.6, y * 2.0) for r, y in fallback], 20):
            geoms.append((poly, n))
    GEOM_CACHE[key] = geoms
    return geoms


def square_center(idx):
    f = (idx - 1) % 8 + 1
    r = (idx - 1) // 8 + 1
    return np.array([(f - 4.5) * TILE, 0.0, -(r - 4.5) * TILE])


def fen_to_board(fen):
    board = [None] * 64
    placement = fen.split(" ")[0]
    rank, file = 8, 1
    for ch in placement:
        if ch == "/":
            rank -= 1
            file = 1
        elif ch.isdigit():
            file += int(ch)
        else:
            color = "w" if ch.isupper() else "b"
            idx = (rank - 1) * 8 + file
            board[idx - 1] = color + ch.upper()
            file += 1
    return board


# ---------------------------------------------------------------- rendering
def render_board(state, cam, supersample=SS):
    w, h = W * supersample, H * supersample
    cam.width, cam.height = w, h
    cam.focal = (h / 2.0) / math.tan(math.radians(cam.fov) / 2.0)
    cam.x_shift *= supersample

    img = Image.new("RGB", (w, h), P["bg"])
    draw = ImageDraw.Draw(img)

    # backdrop: soft vertical gradient + glow behind the board
    top = np.array(P["bg"], dtype=float)
    bottom = np.array((10, 9, 9), dtype=float)
    for y in range(0, h, 4):
        t = y / h
        col = tuple(int(c) for c in (top * (1 - t) + bottom * t))
        draw.rectangle([0, y, w, y + 4], fill=col)

    glow = Image.new("L", (w, h), 0)
    gdraw = ImageDraw.Draw(glow)
    cx, cy = cam.project(np.array([[0, 0, 0]]))[0][0]
    radius = 620 * supersample
    gdraw.ellipse([cx - radius, cy - radius * 0.8, cx + radius, cy + radius * 0.8], fill=70)
    glow = glow.filter(ImageFilter.GaussianBlur(120 * supersample))
    img = Image.composite(Image.new("RGB", (w, h), (58, 56, 50)), img, glow)
    draw = ImageDraw.Draw(img)

    def draw_poly(poly3, color, normal=None, view_ref=None):
        screen, z = cam.project(poly3)
        if np.any(z <= 0.2):
            return
        pts = [tuple(p) for p in screen]
        draw.polygon(pts, fill=color)

    # floor
    floor_y = -1.6
    slab_pts = np.array([[-90, floor_y, -90], [90, floor_y, -90], [90, floor_y, 90], [-90, floor_y, 90]])
    screen, z = cam.project(slab_pts)
    draw.polygon([tuple(p) for p in screen], fill=(24, 22, 21))

    # board slab + rails
    extent = TILE * 8
    pad = 1.4
    rail_h = 0.34
    slab = np.array([
        [-extent / 2 - pad, 0.02, -extent / 2 - pad],
        [extent / 2 + pad, 0.02, -extent / 2 - pad],
        [extent / 2 + pad, 0.02, extent / 2 + pad],
        [-extent / 2 - pad, 0.02, extent / 2 + pad],
    ])
    screen, _ = cam.project(slab)
    draw.polygon([tuple(p) for p in screen], fill=P["border"])
    # side faces of the slab for thickness
    for a, b in ((0, 1), (1, 2), (2, 3), (3, 0)):
        quad = np.array([slab[a], slab[b], slab[b] - [0, 1.02, 0], slab[a] - [0, 1.02, 0]])
        screen, _ = cam.project(quad)
        draw.polygon([tuple(p) for p in screen], fill=(30, 28, 26))
    # raised rails
    rail_quads = []
    for (x0, z0, x1, z1) in [
        (-extent / 2 - pad, extent / 2 + pad, extent / 2 + pad, extent / 2 + pad - 1.4),
        (-extent / 2 - pad, -extent / 2 - pad + 1.4, extent / 2 + pad, -extent / 2 - pad),
        (-extent / 2 - pad, -extent / 2 - pad, -extent / 2 - pad + 1.4, extent / 2 + pad),
        (extent / 2 + pad - 1.4, -extent / 2 - pad, extent / 2 + pad, extent / 2 + pad),
    ]:
        top = np.array([[x0, rail_h, z0], [x1, rail_h, z0], [x1, rail_h, z1], [x0, rail_h, z1]])
        screen, _ = cam.project(top)
        draw.polygon([tuple(p) for p in screen], fill=(46, 43, 40))

    # tiles
    for idx in range(1, 65):
        f = (idx - 1) % 8 + 1
        r = (idx - 1) // 8 + 1
        x0 = (f - 5) * TILE
        z0 = -(r - 5) * TILE
        quad = np.array([[x0, 0, z0], [x0 + TILE, 0, z0], [x0 + TILE, 0, z0 - TILE], [x0, 0, z0 - TILE]])
        base = P["light"] if (f + r) % 2 == 1 else P["dark"]
        # gentle vignette on the far side so the board reads with depth
        screen, z = cam.project(quad)
        depth = float(z.mean())
        fade = max(0.0, min(1.0, (depth - 42) / 60.0))
        col = tuple(int(c * (1 - 0.18 * fade)) for c in base)
        draw.polygon([tuple(p) for p in screen], fill=col)

    # coordinate labels on the rails, exactly like Board3D.buildCoordinates
    extent_half = extent / 2
    for file in range(1, 9):
        letter = "abcdefgh"[file - 1]
        x = (file - 4.5) * TILE
        for z in (extent_half + 0.7, -extent_half - 0.7):
            screen, zz = cam.project(np.array([[x, 0.06, z]]))
            if zz[0] > 0.2:
                draw.text((screen[0][0], screen[0][1]), letter, font=font(13, "bold"),
                          fill=(140, 138, 134), anchor="mm")
    for rank in range(1, 9):
        z = -(rank - 4.5) * TILE
        for x in (extent_half + 0.7, -extent_half - 0.7):
            screen, zz = cam.project(np.array([[x, 0.06, z]]))
            if zz[0] > 0.2:
                draw.text((screen[0][0], screen[0][1]), str(rank), font=font(13, "bold"),
                          fill=(140, 138, 134), anchor="mm")

    # ---- overlay pass (highlights, shadows) on its own layer
    overlay = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    odraw = ImageDraw.Draw(overlay)

    def tile_quad(idx, y=0.035):
        f = (idx - 1) % 8 + 1
        r = (idx - 1) // 8 + 1
        x0 = (f - 5) * TILE
        z0 = -(r - 5) * TILE
        return np.array([[x0, y, z0], [x0 + TILE, y, z0], [x0 + TILE, y, z0 - TILE], [x0, y, z0 - TILE]])

    def fill_tile(idx, color, alpha, inset=0.0):
        f = (idx - 1) % 8 + 1
        r = (idx - 1) // 8 + 1
        x0 = (f - 5) * TILE + inset
        z0 = -(r - 5) * TILE - inset
        quad = np.array([[x0, 0.035, z0], [x0 + TILE - 2 * inset, 0.035, z0],
                         [x0 + TILE - 2 * inset, 0.035, z0 - TILE + 2 * inset], [x0, 0.035, z0 - TILE + 2 * inset]])
        screen, _ = cam.project(quad)
        odraw.polygon([tuple(p) for p in screen], fill=color + (alpha,))

    last = state.get("lastMove")
    if last:
        fill_tile(last["from"], P["last_move"], 110)
        fill_tile(last["to"], P["last_move"], 130)

    if state.get("checkSquare"):
        fill_tile(state["checkSquare"], P["check"], 120)

    if state.get("selected"):
        fill_tile(state["selected"], P["select"], 150)

    for target in state.get("legalTargets", []):
        idx = target["to"]
        center = square_center(idx) + np.array([0, 0.045, 0])
        if target.get("capture"):
            half = TILE / 2 - 0.18
            thick = 0.30
            quads = [
                [center + [-half, 0, -half], center + [half, 0, -half], center + [half, 0, -half + thick], center + [-half, 0, -half + thick]],
                [center + [-half, 0, half - thick], center + [half, 0, half - thick], center + [half, 0, half], center + [-half, 0, half]],
                [center + [-half, 0, -half], center + [-half + thick, 0, -half], center + [-half + thick, 0, half], center + [-half, 0, half]],
                [center + [half - thick, 0, -half], center + [half, 0, -half], center + [half, 0, half], center + [half - thick, 0, half]],
            ]
            for q in quads:
                screen, _ = cam.project(np.array(q))
                odraw.polygon([tuple(p) for p in screen], fill=P["legal_dot"] + (150,))
        else:
            disc = circle_poly(center, 0.62)
            screen, _ = cam.project(disc)
            odraw.polygon([tuple(p) for p in screen], fill=P["legal_dot"] + (140,))

    # contact shadows under pieces
    for idx, piece in enumerate(fen_to_board(state["fen"]), start=1):
        if not piece:
            continue
        c = square_center(idx) + np.array([-0.22, 0.02, 0.18])
        shadow = circle_poly(c, 0.58, 18)
        screen, _ = cam.project(shadow)
        odraw.polygon([tuple(p) for p in screen], fill=(0, 0, 0, 80))

    overlay = overlay.filter(ImageFilter.GaussianBlur(1.0 * supersample))
    img = Image.alpha_composite(img.convert("RGBA"), overlay).convert("RGB")
    draw = ImageDraw.Draw(img)

    # ---- pieces, painter's algorithm
    polys = []
    for idx, piece in enumerate(fen_to_board(state["fen"]), start=1):
        if not piece:
            continue
        color, ptype = piece[0], piece[1]
        yaw = PIECE_YAW.get(ptype, 0) + (180 if color == "b" else 0)
        origin = square_center(idx)
        base = P["white_piece"] if color == "w" else P["black_piece"]
        for poly, normal in piece_geometry(ptype, yaw):
            world = poly + origin
            centroid = world.mean(axis=0)
            depth = float(((centroid - cam.eye) @ cam.R.T)[2])
            polys.append((depth, world, normal, centroid, base))

    polys.sort(key=lambda item: -item[0])
    for depth, world, normal, centroid, base in polys:
        view = norm(cam.eye - centroid)
        if float(np.dot(norm(np.asarray(normal, dtype=float)), view)) <= 0.0:
            continue  # backface cull
        is_dark = base is P["black_piece"]
        col = shade(base, normal, view,
                    spec_strength=0.34 if is_dark else 0.22,
                    rim_strength=0.42 if is_dark else 0.26)
        screen, z = cam.project(world)
        if np.any(z <= 0.2):
            continue
        draw.polygon([tuple(p) for p in screen], fill=col)

    return img


def circle_poly(center, radius, segs=24):
    pts = []
    for i in range(segs):
        a = 2 * math.pi * i / segs
        pts.append([center[0] + radius * math.cos(a), center[1], center[2] + radius * math.sin(a)])
    return np.array(pts)


# ---------------------------------------------------------------- HUD
def rr(draw, box, radius, fill=None, outline=None, width=1):
    draw.rounded_rectangle(box, radius=radius, fill=fill, outline=outline, width=width)


def txt(draw, xy, s, f, fill, anchor="lt"):
    draw.text(xy, s, font=f, fill=fill, anchor=anchor)


def fit(draw, xy, string, f, fill, max_px, anchor="lt"):
    """Draw text, trimming with an ellipsis so it never runs into the clock."""
    limit = max_px * SS
    if draw.textlength(string, font=f) <= limit:
        draw.text(xy, string, font=f, fill=fill, anchor=anchor)
        return
    base = string
    while len(base) > 1:
        base = base[:-1]
        trial = base.rstrip() + "…"
        if draw.textlength(trial, font=f) <= limit:
            draw.text(xy, trial, font=f, fill=fill, anchor=anchor)
            return
    draw.text(xy, "", font=f, fill=fill, anchor=anchor)


def draw_glyph(draw, box, ptype, is_white, alpha=255):
    """Mini piece silhouette, mirroring Hud.glyphFor()."""
    x, y, w, h = box
    color = P["white_piece"] if is_white else (46, 44, 42)
    edge = (120, 118, 112)

    def part(rx, ry, rw, rh, rad=0, rot=None):
        px = x + rx * w
        py = y + ry * h
        pw = max(1, rw * w)
        ph = max(1, rh * h)
        layer = Image.new("RGBA", (int(pw) + 4, int(ph) + 4), (0, 0, 0, 0))
        d = ImageDraw.Draw(layer)
        thin = 1 if min(pw, ph) >= 22 else 0
        d.rounded_rectangle([2, 2, pw + 1, ph + 1], radius=rad, fill=color + (alpha,),
                            outline=(edge + (alpha,)) if thin else None, width=thin)
        if rot:
            layer = layer.rotate(rot, resample=Image.BICUBIC, expand=False)
        return layer, (px - 2, py - 2)

    layers = []
    layers.append(part(0.14, 0.80, 0.72, 0.10, 2))
    if ptype == "P":
        layers.append(part(0.34, 0.10, 0.32, 0.34, min(w, h) * 0.16))
        layers.append(part(0.38, 0.44, 0.24, 0.36, 2))
    elif ptype == "R":
        layers.append(part(0.26, 0.26, 0.48, 0.54, 1))
        for rx in (0.22, 0.44, 0.66):
            layers.append(part(rx, 0.12, 0.12, 0.16, 1))
    elif ptype == "N":
        layers.append(part(0.30, 0.30, 0.34, 0.50, 3, rot=10))
        layers.append(part(0.36, 0.10, 0.42, 0.30, 5, rot=-8))
        layers.append(part(0.34, 0.30, 0.20, 0.26, 2, rot=-24))
    elif ptype == "B":
        layers.append(part(0.40, 0.06, 0.20, 0.20, min(w, h) * 0.1))
        layers.append(part(0.32, 0.26, 0.36, 0.54, 3))
    elif ptype == "Q":
        layers.append(part(0.38, 0.10, 0.24, 0.22, min(w, h) * 0.1))
        layers.append(part(0.28, 0.30, 0.44, 0.50, 2))
        layers.append(part(0.24, 0.06, 0.10, 0.10, min(w, h) * 0.05))
        layers.append(part(0.66, 0.06, 0.10, 0.10, min(w, h) * 0.05))
    elif ptype == "K":
        layers.append(part(0.44, 0.02, 0.12, 0.26, 1))
        layers.append(part(0.34, 0.08, 0.32, 0.12, 1))
        layers.append(part(0.30, 0.30, 0.40, 0.50, 2))
    return layers


def blit_glyph(img, box, ptype, is_white):
    layers = draw_glyph(ImageDraw.Draw(img), box, ptype, is_white)
    for layer, pos in layers:
        img.alpha_composite(layer, (int(pos[0]), int(pos[1])))


PIECE_YAW_FALLBACK = {"N": 180}

EVAL_SYMBOL_COLORS = {
    "!!": (27, 172, 166),
    "!": (92, 139, 176),
    "★": (129, 182, 76),
    "?!": (247, 198, 49),
    "?": (255, 164, 89),
    "??": (250, 65, 45),
}


def format_eval(cp, mate=None):
    if mate is not None:
        if abs(mate) >= 100:
            return "1-0" if mate > 0 else "0-1"
        if mate == 0:
            return "="
        return "M%d" % abs(mate)
    cp = cp or 0
    sign = "+" if cp >= 0 else "-"
    value = abs(cp) / 100.0
    if value < 10:
        return "%s%.1f" % (sign, value)
    return "%s%d" % (sign, int(round(value)))


def s(v):
    """scale a design pixel value to the supersampled canvas"""
    return int(v * SS)


MATERIAL = {"P": 1, "N": 3, "B": 3, "R": 5, "Q": 9, "K": 0}


def _material_advantage(captured):
    """Captured pieces are the opponent's pieces, so this is the +N badge."""
    return sum(MATERIAL.get(p, 0) for p in captured)


def draw_eval_bar(d, layer, state, R):
    """Vertical evaluation bar to the left of the board, like the review view."""
    ev = state.get("evalCp")
    mate = state.get("evalMate")
    if ev is None and mate is None:
        return
    bx, by, bw, bh = 152, 250, 15, 460
    rr(d, R(bx, by, bx + bw, by + bh), s(9), fill=(52, 50, 46, 255), outline=P["stroke"] + (255,), width=s(1))
    # logistic curve so a +2.0 position is not drawn as a full bar
    cp = 0 if ev is None else max(-1200, min(1200, ev))
    frac = 1.0 / (1.0 + math.exp(-0.0035 * cp))
    if mate is not None:
        frac = 1.0 if mate > 0 else 0.0
    fill_h = max(6, int((bh - 4) * frac))
    rr(d, R(bx + 2, by + bh - 2 - fill_h, bx + bw - 2, by + bh - 2), s(7), fill=(238, 238, 210, 255))
    label = format_eval(ev if ev is not None else 0, mate)
    txt(d, (s(bx + bw / 2), s(by - 16)), label, font(12, "bold", mono=True), P["text"], anchor="mm")


def draw_review_card(d, layer, state, x0, y, inner, R):
    """Accuracy cards, classification counts, eval curve and key moments."""
    report = state.get("analysis") or {}
    players = report.get("players", {})
    moves = report.get("moves", [])
    height = 302
    rr(d, R(x0, y, x0 + inner, y + height), s(8), fill=P["panel"] + (255,))
    txt(d, (s(x0 + 14), s(y + 18)), "GAME REVIEW", font(11, "bold"), P["text_dim"], anchor="lm")

    you = state.get("youAre", "w")
    for i, (colour, label) in enumerate([("w", "White"), ("b", "Black")]):
        cx = x0 + 12 + i * (inner / 2 - 6)
        cw = inner / 2 - 18
        rr(d, R(cx, y + 32, cx + cw, y + 92), s(6), fill=P["panel_hover"] + (255,))
        txt(d, (s(cx + 12), s(y + 46)), label + ("  (you)" if colour == you else ""),
            font(11, "bold"), P["text_muted"], anchor="lm")
        accuracy = (players.get(colour) or {}).get("accuracy", 0)
        txt(d, (s(cx + 12), s(y + 72)), "%.1f" % accuracy, font(26, "black"),
            P["accent"] if colour == you else P["text"], anchor="lm")
        txt(d, (s(cx + 12 + 58), s(y + 76)), "%", font(13, "bold"), P["text_dim"], anchor="lm")

    # classification counts
    counts = {"!!": 0, "!": 0, "★": 0, "?!": 0, "?": 0, "??": 0}
    for move in moves:
        if move.get("symbol") in counts:
            counts[move["symbol"]] += 1
    cy = y + 100
    txt(d, (s(x0 + 14), s(cy + 9)), "MOVES", font(10, "bold"), P["text_dim"], anchor="lm")
    bx = x0 + 62
    for symbol, key in zip(["!!", "!", "★", "?!", "?", "??"], ["!!", "!", "★", "?!", "?", "??"]):
        if counts[symbol] == 0:
            continue
        rr(d, R(bx, cy, bx + 44, cy + 20), s(4), fill=P["panel_hover"] + (255,))
        txt(d, (s(bx + 8), s(cy + 10)), symbol, font(11, "bold"),
            EVAL_SYMBOL_COLORS.get(symbol, P["text"]), anchor="lm")
        txt(d, (s(bx + 30), s(cy + 10)), str(counts[symbol]), font(11, "bold"), P["text"], anchor="lm")
        bx += 50

    # eval curve
    graph = report.get("evalGraph") or []
    gx, gy, gw, gh = x0 + 14, y + 130, inner - 28, 74
    rr(d, R(gx, gy, gx + gw, gy + gh), s(5), fill=(24, 23, 21, 255), outline=P["stroke"] + (200,), width=s(1))
    d.line([s(gx), s(gy + gh / 2), s(gx + gw), s(gy + gh / 2)], fill=P["stroke"] + (255,), width=s(1))
    if len(graph) > 1:
        points = []
        for i, cp in enumerate(graph):
            capped = max(-800, min(800, cp))
            px = gx + (gw * i / (len(graph) - 1))
            py = gy + gh / 2 - (capped / 800.0) * (gh / 2 - 4)
            points.append((s(px), s(py)))
        d.line(points, fill=P["accent"] + (255,), width=s(2), joint="curve")
        for point in points:
            d.ellipse([point[0] - s(2), point[1] - s(2), point[0] + s(2), point[1] + s(2)],
                      fill=P["accent"] + (255,))

    # key moments: the three most expensive moves
    bad = {"inaccuracy", "mistake", "blunder"}
    ranked = [m for m in moves if m.get("label") in bad]
    ranked = sorted(ranked, key=lambda m: m.get("loss", 0), reverse=True)[:3]
    if not ranked:
        ranked = sorted(moves, key=lambda m: m.get("loss", 0), reverse=True)[:2]
    ky = gy + gh + 22
    txt(d, (s(gx), s(gy + gh + 12)), "KEY MOMENTS", font(10, "bold"), P["text_dim"], anchor="lm")
    for i, move in enumerate(ranked):
        row_y2 = ky + i * 24
        symbol = move.get("symbol") or ""
        txt(d, (s(gx), s(row_y2 + 10)), "%d." % (i + 1), font(11, "regular"), P["text_dim"], anchor="lm")
        txt(d, (s(gx + 18), s(row_y2 + 10)), move.get("san", ""), font(12, "bold"), P["text"], anchor="lm")
        txt(d, (s(gx + 82), s(row_y2 + 10)), symbol, font(11, "bold"),
            EVAL_SYMBOL_COLORS.get(symbol, P["text_muted"]), anchor="lm")
        txt(d, (s(gx + 106), s(row_y2 + 10)), move.get("labelName", ""), font(11, "regular"),
            P["text_muted"], anchor="lm")
        if move.get("bestSan"):
            txt(d, (s(gx + gw), s(row_y2 + 10)), "best: " + move["bestSan"], font(11, "regular"),
                P["text_dim"], anchor="rm")
    return y + height


def draw_hud(img, state):
    """Draws the chess.com-ish HUD at design resolution (1600x1000)."""
    layer = Image.new("RGBA", (W * SS, H * SS), (0, 0, 0, 0))
    d = ImageDraw.Draw(layer)

    def R(*vals):
        return [s(v) for v in vals]

    # modal dim over the 3D viewport only (the side panel stays readable)
    if state.get("dialog") in ("gameover", "promotion"):
        d.rectangle([0, 0, s(1216), H * SS], fill=(0, 0, 0, 150))

    # ---------------------------------------------------------- side panel
    px, py = 1222, 18
    pw, ph = 360, 964
    rr(d, R(px, py, px + pw, py + ph), s(10), fill=P["panel_raised"] + (255,), outline=P["stroke"] + (255,), width=s(1))

    x0 = px + 12
    inner = pw - 24

    # header
    rr(d, R(x0, py + 12, x0 + inner, py + 12 + 46), s(8), fill=P["panel"] + (255,))
    txt(d, (s(x0 + 14), s(py + 12 + 8)), "CHESS", font(20, "black"), P["text"])
    txt(d, (s(x0 + 14), s(py + 12 + 28)), "Rapid · %d min" % (state.get("timeControl", 600) // 60),
        font(12, "regular"), P["text_muted"])
    d.ellipse(R(x0 + inner - 24, py + 12 + 16, x0 + inner - 16, py + 12 + 24), fill=P["accent"] + (255,))

    y = py + 12 + 46 + 10
    you = state.get("youAre", "w")
    sides = state.get("sides", {})
    white = sides.get("w", {})
    black = sides.get("b", {})
    top_side, bottom_side = (black, white) if you == "w" else (white, black)
    top_color, bottom_color = ("b", "w") if you == "w" else ("w", "b")

    def card(y, side, color, is_self, clock_seconds, active, captured, captured_is_white):
        rr(d, R(x0, y, x0 + inner, y + 96), s(8), fill=P["panel"] + (255,))
        # avatar
        av = R(x0 + 12, y + 12, x0 + 60, y + 60)
        rr(d, av, s(8), fill=P["panel_hover"] + (255,))
        if side.get("kind") == "bot":
            txt(d, (s(x0 + 12 + 24), s(y + 12 + 24)), "C", font(20, "bold"), P["accent"], anchor="mm")
        else:
            initial = (side.get("name") or "?")[:1].upper()
            d.ellipse(R(x0 + 12, y + 12, x0 + 60, y + 60), fill=(66, 64, 61, 255))
            txt(d, (s(x0 + 12 + 24), s(y + 12 + 24)), initial, font(20, "bold"), P["text_muted"], anchor="mm")
        if active:
            d.rounded_rectangle(av, radius=s(8), outline=P["accent"] + (255,), width=s(2))

        name = side.get("name") or "Waiting…"
        name = name.split(" (")[0]
        if is_self:
            name += "  (you)"
        fit(d, (s(x0 + 72), s(y + 13)), name, font(16, "bold"), P["text"], inner - 72 - 128)

        meta = []
        if side.get("kind") == "bot":
            meta.append("Advanced")
            meta.append("1600")
        elif side.get("kind") == "player":
            meta.append("Rating %d" % (1000 + (side.get("userId", 0) % 700)))
        else:
            meta.append("Empty seat")
        if state.get("increment", 0):
            meta.append("+%ds" % state["increment"])
        txt(d, (s(x0 + 72), s(y + 34)), " · ".join(meta), font(12, "regular"), P["text_muted"])

        # captured pieces + material advantage
        cx = x0 + 72
        for ptype in captured[:10]:
            blit_glyph(layer, (s(cx), s(y + 54), s(18), s(18)), ptype, captured_is_white)
            cx += 20
        advantage = _material_advantage(captured)
        if advantage > 0:
            txt(d, (s(cx + 4), s(y + 63)), "+%d" % advantage, font(12, "bold"), P["text_muted"], anchor="lm")

        # clock
        clk = "%d:%02d" % (int(clock_seconds) // 60, int(clock_seconds) % 60)
        rr(d, R(x0 + inner - 116, y + 20, x0 + inner - 12, y + 76), s(6), fill=P["panel_hover"] + (255,))
        low = clock_seconds <= 20
        col = P["text"] if active and not low else (P["clock_low"] if active and low else P["text_muted"])
        if active:
            d.rounded_rectangle(R(x0 + inner - 116, y + 20, x0 + inner - 12, y + 76), radius=s(6),
                                outline=P["accent"] + (180,), width=s(1))
        txt(d, (s(x0 + inner - 64), s(y + 48)), clk, font(30, "bold", mono=True), col, anchor="mm")

    clocks = state.get("clocks", {"w": 600, "b": 600})
    playing = state.get("status") == "playing"
    turn = state.get("turn")
    captured = state.get("captured", {"w": [], "b": []})

    card(y, top_side, top_color, you == top_color, clocks[top_color],
         playing and turn == top_color,
         captured["w"] if top_color == "b" else captured["b"], top_color == "b")
    y += 96 + 10

    review = state.get("view") == "review"
    # move list
    ml_h = 232 if review else 550
    rr(d, R(x0, y, x0 + inner, y + ml_h), s(8), fill=P["panel"] + (255,))
    rr(d, R(x0, y, x0 + inner, y + 34), s(8), fill=P["panel"] + (255,))
    txt(d, (s(x0 + 14), s(y + 17)), "MOVES", font(12, "bold"), P["text_dim"], anchor="lm")
    if state.get("checkSquare"):
        txt(d, (s(x0 + inner - 14), s(y + 17)), "CHECK", font(11, "bold"), P["clock_low"], anchor="rm")

    moves = state.get("moves", [])
    analysis_moves = (state.get("analysis") or {}).get("moves") or []
    row_y = y + 38
    max_rows = (ml_h - 44) // 24
    start_row = max(0, math.ceil(len(moves) / 2) - max_rows)
    for row in range(start_row, math.ceil(len(moves) / 2)):
        ry = row_y + (row - start_row) * 24
        txt(d, (s(x0 + 12), s(ry + 11)), "%d." % (row + 1), font(12, "regular"), P["text_dim"], anchor="lm")
        for col in range(2):
            mi = row * 2 + col
            if mi >= len(moves):
                break
            is_last = mi == len(moves) - 1
            cell_x = x0 + 40 + col * ((inner - 40) / 2 - 4)
            cell_w = (inner - 40) / 2 - 8
            if is_last:
                rr(d, R(cell_x, ry, cell_x + cell_w, ry + 22), s(4), fill=P["panel_hover"] + (255,))
            txt(d, (s(cell_x + 8), s(ry + 11)), moves[mi], font(13, "bold" if is_last else "regular"),
                P["text"] if is_last else P["text_muted"], anchor="lm")
            symbol = analysis_moves[mi].get("symbol") if mi < len(analysis_moves) else ""
            if symbol:
                colour = EVAL_SYMBOL_COLORS.get(symbol, P["text_muted"])
                txt(d, (s(cell_x + cell_w - 8), s(ry + 11)), symbol, font(12, "bold"), colour, anchor="rm")
    y += ml_h + 10

    if review:
        y = draw_review_card(d, layer, state, x0, y, inner, R) + 10

    card(y, bottom_side, bottom_color, you == bottom_color, clocks[bottom_color],
         playing and turn == bottom_color,
         captured["w"] if bottom_color == "b" else captured["b"], bottom_color == "b")
    y += 96 + 10

    # action bar
    labels = ["Resign", "Draw", "Flip"]
    if review:
        labels = ["New game", "Flip"]
    elif state.get("status") == "over":
        labels = ["Flip"]
    for i, label in enumerate(labels):
        bx = x0 + i * (inner / 4)
        bw = inner / 4 - 7
        primary = (label == "Resign" and False) or False
        rr(d, R(bx, y, bx + bw, y + 40), s(6), fill=P["panel_hover"] + (255,))
        txt(d, (s(bx + bw / 2), s(y + 20)), label, font(13, "bold"), P["text"], anchor="mm")
    y += 40 + 10

    if review:
        rr(d, R(x0, y, x0 + inner, y + 46), s(8), fill=P["panel"] + (255,))
        source = (state.get("analysis") or {}).get("source", "Stockfish")
        txt(d, (s(x0 + 12), s(y + 16)), "REVIEW BY", font(10, "bold"), P["text_dim"], anchor="lm")
        txt(d, (s(x0 + 12), s(y + 33)), source, font(13, "bold"), P["text"], anchor="lm")
        txt(d, (s(x0 + inner - 12), s(y + 33)), "Game over", font(11, "regular"), P["text_dim"], anchor="rm")
    else:
        # level bar
        rr(d, R(x0, y, x0 + inner, y + 62), s(8), fill=P["panel"] + (255,))
        txt(d, (s(x0 + 10), s(y + 13)), "COMPUTER STRENGTH", font(10, "bold"), P["text_dim"], anchor="lm")
        levels = ["Beginner", "Intermediate", "Advanced", "Master"]
        for i, label in enumerate(levels):
            bx = x0 + 3 + i * (inner / 4)
            bw = inner / 4 - 6
            active = (i + 1) == state.get("botLevel", 3)
            rr(d, R(bx, y + 26, bx + bw, y + 54), s(5), fill=(P["accent"] if active else P["panel_hover"]) + (255,))
            txt(d, (s(bx + bw / 2), s(y + 40)), label, font(11, "bold" if active else "regular"),
                P["text"] if active else P["text_muted"], anchor="mm")

    # ---------------------------------------------------------- banner
    bw, bh = 320, 40
    bx = W / 2 - bw / 2 - 40
    by = 20
    rr(d, R(bx, by, bx + bw, by + bh), s(20), fill=(38, 36, 33, 245), outline=P["stroke"] + (255,), width=s(1))
    d.ellipse(R(bx + 16, by + 16, bx + 24, by + 24), fill=P["accent"] + (255,))
    status = state.get("status", "playing")
    if status == "over":
        banner = "Checkmate" if state.get("reason") == "checkmate" else (state.get("reason") or "Game over")
    elif state.get("checkSquare"):
        banner = "Check!"
    else:
        banner = ("White" if turn == "w" else "Black") + " to move" + (" · your move" if you == turn else "")
    txt(d, (s(bx + bw / 2 + 10), s(by + bh / 2)), banner, font(14, "bold"), P["text"], anchor="mm")

    # ---------------------------------------------------------- overlays
    if state.get("dialog") == "gameover":
        cw, ch = 420, 220
        cx = W / 2 - cw / 2
        cy = H / 2 - ch / 2
        rr(d, R(cx, cy, cx + cw, cy + ch), s(14), fill=P["panel_raised"] + (255,), outline=P["accent"] + (200,), width=s(2))
        result_colour = {"white": "w", "black": "b"}.get(state.get("result"))
        won = result_colour == you
        title = "You won!" if won else "You lost"
        rr(d, R(cx, cy, cx + cw, cy + 8), s(14), fill=(P["win"] if won else P["loss"]) + (255,))
        txt(d, (s(cx + cw / 2), s(cy + 50)), title, font(26, "black"), P["win"] if won else P["loss"], anchor="mm")
        txt(d, (s(cx + cw / 2), s(cy + 82)), "by " + (state.get("reason") or ""), font(14, "regular"),
            P["text_muted"], anchor="mm")
        rr(d, R(cx + cw / 2 - 90, cy + 120, cx + cw / 2 + 90, cy + 164), s(8), fill=P["accent"] + (255,))
        txt(d, (s(cx + cw / 2), s(cy + 142)), "New game", font(15, "bold"), P["text"], anchor="mm")
        rr(d, R(cx + cw / 2 + 100, cy + 120, cx + cw / 2 + 220, cy + 164), s(8), fill=P["panel_hover"] + (255,))
        txt(d, (s(cx + cw / 2 + 160), s(cy + 142)), "Review", font(14, "regular"), P["text"], anchor="mm")

    if state.get("dialog") == "promotion":
        cw, ch = 380, 168
        cx = W / 2 - cw / 2
        cy = H / 2 - ch / 2
        rr(d, R(cx, cy, cx + cw, cy + ch), s(12), fill=P["panel_raised"] + (255,), outline=P["stroke"] + (255,), width=s(1))
        txt(d, (s(cx + 20), s(cy + 25)), "Promote to", font(16, "bold"), P["text"], anchor="lm")
        for i, (code, label) in enumerate([("Q", "Queen"), ("R", "Rook"), ("B", "Bishop"), ("N", "Knight")]):
            bx0 = cx + 20 + i * 88
            by0 = cy + 44
            rr(d, R(bx0, by0, bx0 + 80, by0 + 84), s(8), fill=P["panel_hover"] + (255,),
               outline=P["stroke"] + (180,), width=s(1))
            blit_glyph(layer, (s(bx0 + 20), s(by0 + 8), s(40), s(40)), code, state.get("youAre") == "w")
            txt(d, (s(bx0 + 40), s(by0 + 68)), label, font(11, "regular"), P["text_muted"], anchor="mm")

    if state.get("evalCp") is not None or state.get("evalMate") is not None:
        draw_eval_bar(d, layer, state, R)

    if state.get("toast"):
        tw, th = 360, 40
        tx = W / 2 - tw / 2
        ty = H - 70 - th
        rr(d, R(tx, ty, tx + tw, ty + th), s(8), fill=P["panel"] + (250,), outline=P["stroke"] + (255,))
        txt(d, (s(tx + tw / 2), s(ty + th / 2)), state["toast"], font(13, "regular"), P["text"], anchor="mm")

    img.alpha_composite(layer, (0, 0))
    return img


# ---------------------------------------------------------------- main
def compose(state):
    cam_cfg = state.get("camera", {})
    cam = Camera(cam_cfg.get("eye", [0, 34, 40]), cam_cfg.get("focus", [0, 0, 0]),
                 cam_cfg.get("fov", 42), x_shift=-80)
    board_img = render_board(state, cam).convert("RGBA")
    vw, vh = board_img.size

    # subtle vignette
    vig = Image.new("L", (vw, vh), 0)
    vd = ImageDraw.Draw(vig)
    vd.ellipse([-vw * 0.25, -vh * 0.35, vw * 1.25, vh * 1.3], fill=255)
    vig = vig.filter(ImageFilter.GaussianBlur(180 * SS / 2))
    dark = Image.new("RGBA", (vw, vh), (0, 0, 0, 150))
    board_img = Image.composite(board_img, Image.alpha_composite(board_img, dark), vig)

    if not state.get("no_hud"):
        board_img = draw_hud(board_img, state)
    return board_img.convert("RGB").resize((W, H), Image.LANCZOS)


def contact_sheet(paths, out_path, cols=2, scale=0.5):
    thumbs = []
    for path in paths:
        im = Image.open(path)
        im = im.resize((int(im.width * scale), int(im.height * scale)), Image.LANCZOS)
        thumbs.append(im)
    if not thumbs:
        return
    tw, th = thumbs[0].size
    rows = (len(thumbs) + cols - 1) // cols
    gap = 12
    sheet = Image.new("RGB", (cols * tw + (cols + 1) * gap, rows * th + (rows + 1) * gap), (18, 17, 16))
    for i, thumb in enumerate(thumbs):
        x = gap + (i % cols) * (tw + gap)
        y = gap + (i // cols) * (th + gap)
        sheet.paste(thumb, (x, y))
    sheet.save(out_path, quality=95)
    print("wrote", out_path, sheet.size)


def main():
    with open(STATES) as fh:
        payload = json.load(fh)
    os.makedirs(RENDERS, exist_ok=True)
    written = []
    for state in payload["scenes"]:
        img = compose(state)
        out = os.path.join(RENDERS, state["file"])
        img.save(out, quality=95)
        written.append(out)
        print("wrote", out, img.size)

    sheet = os.path.join(RENDERS, "06_piece_sheet.png")
    if os.path.exists(sheet):
        written.append(sheet)
    contact_sheet(written, os.path.join(RENDERS, "00_overview.png"))


if __name__ == "__main__":
    main()
